<?php use Luna\Core\View; ?>
<div class="page-actions"><form method="get" class="search-form"><label>Dal <input type="date" name="from" value="<?= View::e($from) ?>"></label><label>Al <input type="date" name="to" value="<?= View::e($to) ?>"></label><button class="button">Ricalcola</button></form><a class="button" href="/accounting/journal">Prima nota</a></div>
<section class="card table-wrap"><table><thead><tr><th>Conto</th><th>Descrizione</th><th>Tipo</th><th>Dare</th><th>Avere</th><th>Saldo</th></tr></thead><tbody><?php foreach ($accounts as $account): ?><tr><td><a href="/accounting/ledger/<?= (int) $account['id'] ?>"><?= View::e($account['code']) ?></a></td><td><?= View::e($account['name']) ?></td><td><?= View::e($account['account_type']) ?></td><td><?= View::money($account['debit']) ?></td><td><?= View::money($account['credit']) ?></td><td><?= View::money($account['balance']) ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><th colspan="3">Totali</th><th><?= View::money($totals['debit']) ?></th><th><?= View::money($totals['credit']) ?></th><th class="<?= abs($totals['debit'] - $totals['credit']) > .005 ? 'danger-text' : '' ?>"><?= View::money($totals['debit'] - $totals['credit']) ?></th></tr></tfoot></table></section>
